import type { AIConfig, AIAction, AIResponse, Task, Memory, CalendarEvent } from '../shared/types';
import { generateId, isoNow } from '../shared/utils';

// ── Calendar fetcher type ──────────────────────────────────────────────────────

/** Callback the AI client uses to fetch calendar events for an arbitrary range. */
export type CalendarFetcher = (startDate: string, endDate: string) => Promise<CalendarEvent[]>;

// ── Tool definitions ──────────────────────────────────────────────────────────

const ANTHROPIC_CAL_TOOL = {
  name: 'get_calendar_events',
  description:
    "Fetch the user's Google Calendar events for a date range. " +
    'Use this for any date more than 14 days from today, or when the pre-fetched ' +
    'context does not contain the requested date.',
  input_schema: {
    type: 'object' as const,
    properties: {
      start_date: { type: 'string', description: 'Start date YYYY-MM-DD (inclusive)' },
      end_date:   { type: 'string', description: 'End date YYYY-MM-DD (inclusive)' },
    },
    required: ['start_date', 'end_date'],
  },
};

const OPENAI_CAL_TOOL = {
  type: 'function' as const,
  function: {
    name: 'get_calendar_events',
    description:
      "Fetch the user's Google Calendar events for a date range. " +
      'Use this for any date more than 14 days from today, or when the pre-fetched ' +
      'context does not contain the requested date.',
    parameters: {
      type: 'object',
      properties: {
        start_date: { type: 'string', description: 'Start date YYYY-MM-DD (inclusive)' },
        end_date:   { type: 'string', description: 'End date YYYY-MM-DD (inclusive)' },
      },
      required: ['start_date', 'end_date'],
    },
  },
};

// ── System prompt ─────────────────────────────────────────────────────────────

function buildSystemPrompt(): string {
  const now = new Date();
  const dateStr = now.toLocaleDateString('en-US', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  });
  const timeStr = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

  return `You are a personal planning assistant embedded in a browser extension.
Today is ${dateStr}, ${timeStr}.
You manage tasks, memory, and calendar events. Return ONLY valid JSON — no markdown, no prose wrappers.

EXACT output schema — follow this precisely:
{
  "message": "Your reply to the user. For action confirmations be brief. For information queries (listing events, listing tasks, answering questions) write the FULL answer — include all event titles, times, and dates. Do NOT truncate or summarise.",
  "actions": [
    { "type": "<action_type>", "payload": { ...fields } }
  ],
  "requiresApproval": false
}

Each action MUST have a "type" field and a "payload" object. Example:
  { "type": "create_task", "payload": { "title": "Buy groceries", "priority": "medium" } }

Action types and payload fields:
  create_task           payload: { title, status?, priority?, estimated_duration_minutes?, due_date?, project?, notes? }
  update_task           payload: { id, ...fields to change }
  delete_task           payload: { id }
  reorder_tasks         payload: { orderedIds: ["id1","id2",...] }
  plan_day              payload: { orderedTasks: [{ id, estimated_duration_minutes? }] }
  update_memory         payload: { path: "dot.key", value: any }
  create_calendar_event payload: { title, start (ISO datetime), end (ISO datetime), description? }
  delete_calendar_event payload: { id } — use the event id from the calendar list

Rules:
- requiresApproval = false always (except explicit bulk deletes — then set to true)
- Tasks are flexible work items. Calendar events are fixed-time appointments only.
- Infer priority from language: "urgent/asap/due today" → high, "sometime/eventually" → low
- "plan my day" → reorder todo tasks by priority+duration, fill in durations
- "mark X done" → update_task with status:"done"
- Extract tasks from screenshots literally — preserve exact wording

Calendar rules:
- The context has pre-fetched events for today + next 14 days only.
- For ANY date beyond that 14-day window, you MUST call get_calendar_events before answering. Do NOT say "no events" or "not in my data" for future dates — always fetch first.
- Pass YYYY-MM-DD start_date/end_date. Widen to cover the full requested period (e.g. full week or month) with one call rather than multiple narrow calls.
- After receiving tool results, answer from those results literally. Never invent events.
- For dates within the 14-day window, read from the pre-fetched list. Quote every matching event title and time.
- When asked about a specific day, calculate the date using "Today is ${dateStr}", then look it up.
- If the pre-fetched list has zero events for an in-window day, say: "I don't see any events on [date]." — do NOT just say "No events."`;
}

// ── AI Client ─────────────────────────────────────────────────────────────────

export class AIClient {
  constructor(private cfg: AIConfig) {}

  async sendCommand(
    prompt:         string,
    tasks:          Task[],
    memory:         Memory,
    calendar:       CalendarEvent[],
    imageData?:     string,
    fetchCalendar?: CalendarFetcher,
  ): Promise<AIResponse> {
    const context = buildContext(tasks, memory, calendar);
    return this.cfg.provider === 'anthropic'
      ? this.callAnthropic(prompt, context, imageData, fetchCalendar)
      : this.callOpenAI(prompt, context, imageData, fetchCalendar);
  }

  private async callAnthropic(
    prompt:         string,
    context:        string,
    imageData?:     string,
    fetchCalendar?: CalendarFetcher,
  ): Promise<AIResponse> {
    type Block = Record<string, unknown>;
    type Msg   = { role: 'user' | 'assistant'; content: Block[] };

    const initContent: Block[] = [];
    if (imageData) {
      initContent.push({
        type:   'image',
        source: { type: 'base64', media_type: 'image/png', data: imageData },
      });
    }
    initContent.push({ type: 'text', text: `${context}\n\nUser: ${prompt}` });

    const messages: Msg[] = [{ role: 'user', content: initContent }];
    const tools = fetchCalendar ? [ANTHROPIC_CAL_TOOL] : [];

    for (let turn = 0; turn < 5; turn++) {
      const res = await fetch('https://api.anthropic.com/v1/messages', {
        method:  'POST',
        headers: {
          'x-api-key':         this.cfg.apiKey,
          'anthropic-version': '2023-06-01',
          'content-type':      'application/json',
        },
        body: JSON.stringify({
          model:      this.cfg.model || 'claude-haiku-4-5-20251001',
          max_tokens: 2048,
          system:     buildSystemPrompt(),
          messages,
          ...(tools.length ? { tools } : {}),
        }),
      });

      if (!res.ok) throw new Error(`Anthropic API error ${res.status}: ${await res.text()}`);
      const data = await res.json() as { stop_reason: string; content: Block[] };

      if (data.stop_reason !== 'tool_use') {
        // End turn — find the text block and parse it as our JSON response
        const textBlock = data.content.find((b) => b['type'] === 'text');
        return parseAIResponse((textBlock?.['text'] as string) ?? '');
      }

      // ── Tool use turn ────────────────────────────────────────────────────────
      messages.push({ role: 'assistant', content: data.content });

      const toolResults: Block[] = [];
      for (const block of data.content) {
        if (block['type'] !== 'tool_use') continue;
        const input  = block['input'] as { start_date: string; end_date: string };
        const events = fetchCalendar
          ? await fetchCalendar(input.start_date, input.end_date)
          : [];
        toolResults.push({
          type:        'tool_result',
          tool_use_id: block['id'],
          content:     formatEventsForTool(events, input.start_date, input.end_date),
        });
      }
      messages.push({ role: 'user', content: toolResults });
    }

    throw new Error('Calendar tool: too many turns without a final response.');
  }

  private async callOpenAI(
    prompt:         string,
    context:        string,
    imageData?:     string,
    fetchCalendar?: CalendarFetcher,
  ): Promise<AIResponse> {
    type OAMsg     = Record<string, unknown>;
    type ToolCall  = { id: string; type: string; function: { name: string; arguments: string } };

    const userContent: unknown[] = [];
    if (imageData) {
      userContent.push({
        type:      'image_url',
        image_url: { url: `data:image/png;base64,${imageData}` },
      });
    }
    userContent.push({ type: 'text', text: `${context}\n\nUser: ${prompt}` });

    const messages: OAMsg[] = [
      { role: 'system', content: buildSystemPrompt() },
      { role: 'user',   content: userContent },
    ];
    const tools = fetchCalendar ? [OPENAI_CAL_TOOL] : [];

    for (let turn = 0; turn < 5; turn++) {
      const res = await fetch('https://api.openai.com/v1/chat/completions', {
        method:  'POST',
        headers: {
          Authorization:  `Bearer ${this.cfg.apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          model:      this.cfg.model || 'gpt-4o-mini',
          messages,
          max_tokens: 2048,
          // response_format:json_object is incompatible with tool use; parseAIResponse handles either
          ...(tools.length
            ? { tools }
            : { response_format: { type: 'json_object' } }),
        }),
      });

      if (!res.ok) throw new Error(`OpenAI API error ${res.status}: ${await res.text()}`);
      const data = await res.json() as {
        choices: Array<{
          finish_reason: string;
          message: { role: string; content: string | null; tool_calls?: ToolCall[] };
        }>;
      };

      const choice = data.choices[0];

      if (choice.finish_reason !== 'tool_calls') {
        return parseAIResponse(choice.message.content ?? '');
      }

      // ── Tool use turn ────────────────────────────────────────────────────────
      messages.push(choice.message as OAMsg);

      for (const tc of choice.message.tool_calls ?? []) {
        const args = JSON.parse(tc.function.arguments) as { start_date: string; end_date: string };
        const events = fetchCalendar
          ? await fetchCalendar(args.start_date, args.end_date)
          : [];
        messages.push({
          role:         'tool',
          tool_call_id: tc.id,
          content:      formatEventsForTool(events, args.start_date, args.end_date),
        });
      }
    }

    throw new Error('Calendar tool: too many turns without a final response.');
  }
}

// ── Action application ────────────────────────────────────────────────────────

export interface ApplyResult {
  tasks:                  Task[];
  memory:                 Memory;
  calendarRequests:       Array<{ title: string; start: string; end: string; description?: string }>;
  calendarDeleteRequests: string[];   // event IDs to delete
}

export function applyActions(
  tasks:   Task[],
  memory:  Memory,
  actions: AIAction[],
): ApplyResult {
  let newTasks    = [...tasks];
  const newMem    = JSON.parse(JSON.stringify(memory)) as Memory;
  const calReqs:  ApplyResult['calendarRequests']       = [];
  const calDels:  ApplyResult['calendarDeleteRequests'] = [];

  for (const rawAction of actions) {
    if (!rawAction.type) continue;   // skip malformed action objects
    // Normalise to snake_case so camelCase variants (createTask → create_task) still match
    const action = {
      ...rawAction,
      type: (rawAction.type as string)
        .replace(/([a-z])([A-Z])/g, '$1_$2')
        .toLowerCase()
        .replace(/-/g, '_') as typeof rawAction.type,
    };
    switch (action.type) {

      case 'create_task': {
        // Accept both { payload: {...} } and flat { type, title, ... } formats
        const p = (action.payload ?? action) as Partial<Task>;
        newTasks.push({
          id:         generateId(),
          title:      p.title ?? 'Untitled',
          status:     p.status   ?? 'todo',
          priority:   p.priority ?? 'medium',
          source:     p.source   ?? 'ai',
          estimated_duration_minutes: p.estimated_duration_minutes,
          due_date:   p.due_date,
          project:    p.project,
          notes:      p.notes,
          created_at: isoNow(),
          updated_at: isoNow(),
        });
        break;
      }

      case 'update_task': {
        const p = (action.payload ?? action) as Partial<Task> & { id: string };
        newTasks = newTasks.map((t) =>
          t.id === p.id ? { ...t, ...p, updated_at: isoNow() } : t
        );
        break;
      }

      case 'delete_task': {
        const { id } = (action.payload ?? action) as { id: string };
        newTasks = newTasks.filter((t) => t.id !== id);
        break;
      }

      case 'reorder_tasks': {
        const { orderedIds } = (action.payload ?? action) as { orderedIds: string[] };
        const map = new Map(newTasks.map((t) => [t.id, t]));
        newTasks = orderedIds.map((id) => map.get(id)).filter(Boolean) as Task[];
        break;
      }

      case 'plan_day': {
        const { orderedTasks } = (action.payload ?? action) as {
          orderedTasks: Array<{ id: string; estimated_duration_minutes?: number }>;
        };
        const idxMap = new Map(orderedTasks.map((t, i) => [t.id, i]));
        const durMap = new Map(
          orderedTasks
            .filter((t) => t.estimated_duration_minutes != null)
            .map((t) => [t.id, t.estimated_duration_minutes as number])
        );
        newTasks = [...newTasks].sort((a, b) =>
          (idxMap.get(a.id) ?? 999) - (idxMap.get(b.id) ?? 999)
        );
        newTasks = newTasks.map((t) =>
          durMap.has(t.id)
            ? { ...t, estimated_duration_minutes: durMap.get(t.id), updated_at: isoNow() }
            : t
        );
        break;
      }

      case 'update_memory': {
        const { path, value } = (action.payload ?? action) as { path: string; value: unknown };
        setNested(newMem as unknown as Record<string, unknown>, path, value);
        break;
      }

      case 'create_calendar_event': {
        calReqs.push((action.payload ?? action) as ApplyResult['calendarRequests'][0]);
        break;
      }

      case 'delete_calendar_event': {
        const { id } = (action.payload ?? action) as { id: string };
        if (id) calDels.push(id);
        break;
      }
    }
  }

  return { tasks: newTasks, memory: newMem, calendarRequests: calReqs, calendarDeleteRequests: calDels };
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function buildContext(tasks: Task[], memory: Memory, calendar: CalendarEvent[]): string {
  const now      = new Date();
  const todayStr = dateKey(now);
  const tomorrow = new Date(now); tomorrow.setDate(now.getDate() + 1);
  const tomorrowStr = dateKey(tomorrow);

  const calLines = calendar.length === 0
    ? '(no events in the next 14 days)'
    : calendar.map((e) => {
        const isAllDay = !e.start.includes('T');
        const startDt  = isAllDay ? localNoon(e.start) : new Date(e.start);
        const endDt    = isAllDay ? localNoon(e.end)   : new Date(e.end);
        const dayLabel = startDt.toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' });
        const timeLabel = isAllDay
          ? 'all day'
          : `${startDt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })} – ${endDt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })}`;
        const desc = e.description ? ` | ${e.description.slice(0, 80)}` : '';
        const key = dateKey(startDt);
        const rel = key === todayStr ? ' [TODAY]' : key === tomorrowStr ? ' [TOMORROW]' : '';
        return `• ${dayLabel}${rel} ${timeLabel}: ${e.title}${desc}`;
      }).join('\n');

  return [
    `Tasks (${tasks.length}):\n${JSON.stringify(tasks, null, 2)}`,
    `Memory:\n${JSON.stringify(memory, null, 2)}`,
    `Upcoming calendar events (today + next 14 days only — use get_calendar_events tool for anything beyond, ${calendar.length} total):\n${calLines}`,
  ].join('\n\n');
}

/** Format fetched events as a readable string to return to the AI as a tool result. */
function formatEventsForTool(events: CalendarEvent[], startDate: string, endDate: string): string {
  if (!events.length) {
    return `No events found between ${startDate} and ${endDate}.`;
  }
  return events.map((e) => {
    const isAllDay = !e.start.includes('T');
    const startDt  = isAllDay ? localNoon(e.start) : new Date(e.start);
    const endDt    = isAllDay ? localNoon(e.end)   : new Date(e.end);
    const dayLabel = startDt.toLocaleDateString('en-US', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
    });
    const timeLabel = isAllDay
      ? 'all day'
      : `${startDt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })} – `
        + endDt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
    return `• ${dayLabel} ${timeLabel}: ${e.title}`;
  }).join('\n');
}

function parseAIResponse(raw: string): AIResponse {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  try {
    const parsed = JSON.parse(cleaned) as Partial<AIResponse>;
    return {
      message:          String(parsed.message ?? ''),
      actions:          Array.isArray(parsed.actions) ? parsed.actions : [],
      requiresApproval: parsed.requiresApproval === true,
    };
  } catch {
    return { message: raw.slice(0, 200), actions: [], requiresApproval: false };
  }
}

/** Returns a stable YYYY-MM-DD string in local time for date comparison. */
function dateKey(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/**
 * Parse a bare YYYY-MM-DD all-day event date as local noon.
 * new Date('2026-04-30') is UTC midnight, which becomes Apr 29 in UTC-X zones.
 * Setting it to local noon keeps the correct calendar day in every timezone.
 */
function localNoon(dateStr: string): Date {
  const [y, m, d] = dateStr.split('-').map(Number);
  return new Date(y, m - 1, d, 12, 0, 0);
}

function setNested(obj: Record<string, unknown>, path: string, value: unknown): void {
  const parts = path.split('.');
  let cur = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (cur[parts[i]] == null || typeof cur[parts[i]] !== 'object') cur[parts[i]] = {};
    cur = cur[parts[i]] as Record<string, unknown>;
  }
  cur[parts[parts.length - 1]] = value;
}
