import type { CalendarEvent } from '../shared/types';

interface GCalEvent {
  id:      string;
  summary: string;
  start:   { dateTime?: string; date?: string };
  end:     { dateTime?: string; date?: string };
  description?: string;
}

export class CalendarClient {
  constructor(private accessToken: string) {}

  private get auth(): HeadersInit {
    return { Authorization: `Bearer ${this.accessToken}` };
  }

  // ── Shared fetching core ───────────────────────────────────────────────────

  private async fetchAcrossAllCalendars(
    params: URLSearchParams,
  ): Promise<{ events: CalendarEvent[]; warning?: string }> {
    const calendarIds = new Set<string>(['primary']);
    let warning: string | undefined;

    try {
      const listRes = await fetch(
        'https://www.googleapis.com/calendar/v3/users/me/calendarList',
        { headers: this.auth }
      );
      if (listRes.ok) {
        const list = await listRes.json() as { items?: Array<{ id: string }> };
        for (const c of list.items ?? []) calendarIds.add(c.id);
      } else {
        const body = await listRes.text().catch(() => '');
        warning = `Could not load calendar list (${listRes.status}). ` +
          (listRes.status === 401 || listRes.status === 403
            ? 'Try disconnecting and reconnecting Google in Settings.'
            : body.slice(0, 120));
      }
    } catch (e) {
      warning = `Calendar list fetch failed: ${(e as Error).message}`;
    }

    const fetches = [...calendarIds].map((calId) =>
      fetch(
        `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calId)}/events?${params}`,
        { headers: this.auth }
      )
        .then(async (res): Promise<CalendarEvent[]> => {
          if (!res.ok) return [];
          const data = await res.json() as { items?: GCalEvent[] };
          return (data.items ?? []).map((e): CalendarEvent => ({
            id:          e.id,
            title:       e.summary ?? '(no title)',
            start:       e.start.dateTime ?? e.start.date ?? '',
            end:         e.end.dateTime   ?? e.end.date   ?? '',
            description: e.description,
          }));
        })
        .catch((): CalendarEvent[] => [])
    );

    const batches = await Promise.all(fetches);

    const seen = new Set<string>();
    const all: CalendarEvent[] = [];
    for (const batch of batches) {
      for (const e of batch) {
        if (e.id && !seen.has(e.id)) { seen.add(e.id); all.push(e); }
      }
    }
    all.sort((a, b) => (a.start < b.start ? -1 : 1));

    return { events: all, warning };
  }

  // ── Public API ─────────────────────────────────────────────────────────────

  /**
   * Fetch events across ALL calendars for the next `daysAhead` days.
   * Returns { events, warning } — warning is set if calendarList failed.
   */
  async getUpcomingEvents(daysAhead = 14): Promise<{ events: CalendarEvent[]; warning?: string }> {
    const start = new Date(); start.setHours(0, 0, 0, 0);
    const end   = new Date(start); end.setDate(start.getDate() + daysAhead);

    return this.fetchAcrossAllCalendars(new URLSearchParams({
      timeMin:      start.toISOString(),
      timeMax:      end.toISOString(),
      singleEvents: 'true',
      orderBy:      'startTime',
      maxResults:   '250',
    }));
  }

  /**
   * Fetch events across ALL calendars for an arbitrary YYYY-MM-DD range.
   * Used by the AI tool to look up events beyond the 14-day cache.
   */
  async getEventsForRange(startDate: string, endDate: string): Promise<CalendarEvent[]> {
    // Parse as local midnight / end-of-day so the full local day is covered.
    const start = new Date(`${startDate}T00:00:00`);
    const end   = new Date(`${endDate}T23:59:59`);

    const { events } = await this.fetchAcrossAllCalendars(new URLSearchParams({
      timeMin:      start.toISOString(),
      timeMax:      end.toISOString(),
      singleEvents: 'true',
      orderBy:      'startTime',
      maxResults:   '250',
    }));
    return events;
  }

  async deleteEvent(eventId: string): Promise<void> {
    const res = await fetch(
      `https://www.googleapis.com/calendar/v3/calendars/primary/events/${encodeURIComponent(eventId)}`,
      { method: 'DELETE', headers: this.auth }
    );
    if (!res.ok && res.status !== 410) {
      throw new Error(`Calendar delete error ${res.status}: ${await res.text()}`);
    }
  }

  async createEvent(event: {
    title:        string;
    start:        string;
    end:          string;
    description?: string;
  }): Promise<void> {
    const res = await fetch(
      'https://www.googleapis.com/calendar/v3/calendars/primary/events',
      {
        method:  'POST',
        headers: { ...this.auth, 'Content-Type': 'application/json' },
        body:    JSON.stringify({
          summary:     event.title,
          description: event.description,
          start:       { dateTime: event.start, timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone },
          end:         { dateTime: event.end,   timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone },
        }),
      }
    );
    if (!res.ok) throw new Error(`Calendar create error ${res.status}: ${await res.text()}`);
  }
}
